@lscheeler sorry, I guess I misread it. My issue is a little different then. I'm on 1.0.9

```ts
export class EntityId {
  @PrimaryGeneratedColumn()
  id: number
}

@Entity()
export class Schema extends EntityId {
  @Column()
  name: string

  @Column({ type: 'integer' })
  seqNo: number

  @OneToMany(
    (type) => SchemaField,
    (field) => field.schema,
    {
      cascadeInsert: true,
      eager: true
    }
  )
  fields: SchemaField[]
}

@Entity()
export class SchemaField extends EntityId {
  @Column()
  name: string

  @Column({ type: 'integer' })
  type: SchemaFieldType

  @ManyToMany((type) => Validator)
  @JoinTable()
  constraints: Validator[]

  @ManyToOne(
    (type) => Schema,
    (schema) => schema.fields
  )
  schema: Schema
}

@Entity()
export class Validator extends EntityId {
  @Column()
  name: string

  @Column()
  validator: string

  @Column({
    transformer: {
      from: (val) => val.split(',').map(parseInt),
      to: (val) => val.join(',')
    },
    type: 'text'
  })
  fieldTypes: SchemaFieldType[]
}
```

